  }
  .stat-item { background: rgba(255,255,255,0.05); padding: 8px 16px; border-radius: 8px; }
  .stat-item span { color: #00d4ff; font-weight: bold; }
  #container {
    display: flex;
    align-items: flex-end;
    justify-content: center;
    gap: 4px;
    height: 400px;
