    border-radius: 16px;
    box-shadow: 0 8px 32px rgba(0,0,0,0.3);
  }
  .bar {
    flex: 1;
    background: linear-gradient(to top, #0f3460, #00d4ff);
    border-radius: 6px 6px 0 0;
    transition: height 0.2s, background 0.2s;
    position: relative;
    min-width: 8px;
    max-width: 40px;
  }
  .bar.compare { background: linear-gradient(to top, #ff9f1c, #ffbf69); }
  .bar.swap { background: linear-gradient(to top, #e71d36, #ff4d6d); }
  .bar.sorted { background: linear-gradient(to top, #2d6a4f, #52b788); }
  .bar-label {
    position: absolute;
    bottom: -22px;
    left: 50%;
    transform: translateX(-50%);
    font-size: 11px;
    color: #aaa;
    white-space: nowrap;
  }
  .code-panel {
    margin-top: 20px;
    background: rgba(0,0,0,0.3);
    padding: 16px 24px;
    border-radius: 12px;
    font-family: 'Courier New', monospace;
    font-size: 13px;
    line-height: 1.6;
    max-width: 900px;
    width: 100%;
    overflow-x: auto;
  }
  .code-line { padding: 2px 8px; border-radius: 4px; transition: background 0.2s; }
