  input[type=range] { width: 120px; }
</style>
</head>
<body>
<h1>🔵 冒泡排序可视化</h1>

<div class="controls">
  <button id="btnGenerate">生成随机数组</button>
  <button id="btnSort">开始排序</button>
  <button id="btnStep">单步执行</button>
  <button id="btnAuto">自动播放</button>
  <button id="btnReset">重置</button>
  <div class="slider-group">
    <label for="speed">速度</label>
    <input type="range" id="speed" min="10" max="500" value="100">
    <span id="speedVal">100ms</span>
  </div>
</div>

<div class="stats">
  <div class="stat-item">比较次数: <span id="compareCount">0</span></div>
  <div class="stat-item">交换次数: <span id="swapCount">0</span></div>
  <div class="stat-item">数组长度: <span id="arrayLen">20</span></div>
</div>

<div id="container"></div>

<div class="code-panel">
  <div class="code-line" data-line="0">function bubbleSort(arr) {</div>
  <div class="code-line" data-line="1">  const n = arr.length;</div>
  <div class="code-line" data-line="2">  for (let i = 0; i < n - 1; i++) {</div>
  <div class="code-line" data-line="3">    for (let j = 0; j < n - 1 - i; j++) {</div>
  <div class="code-line" data-line="4">      if (arr[j] > arr[j + 1]) {</div>
  <div class="code-line" data-line="5">        // 交换元素</div>
  <div class="code-line" data-line="6">        [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];</div>
  <div class="code-line" data-line="7">      }</div>
  <div class="code-line" data-line="8">    }</div>
  <div class="code-line" data-line="9">  }</div>
  <div class="code-line" data-line="10">  return arr;</div>
  <div class="code-line" data-line="11">}</div>
</div>

<script>
  const container = document.getElementById('container');
  const btnGenerate = document.getElementById('btnGenerate');
  const btnSort = document.getElementById('btnSort');
  const btnStep = document.getElementById('btnStep');
  const btnAuto = document.getElementById('btnAuto');
  const btnReset = document.getElementById('btnReset');
  const speedInput = document.getElementById('speed');
  const speedVal = document.getElementById('speedVal');
  const compareCountEl = document.getElementById('compareCount');
  const swapCountEl = document.getElementById('swapCount');
  const arrayLenEl = document.getElementById('arrayLen');
  const codeLines = document.querySelectorAll('.code-line');

  let array = [];
  let bars = [];
  let steps = [];
  let currentStep = 0;
  let isAuto = false;
  let autoTimer = null;
  const ARRAY_SIZE = 20;

  function generateArray() {
    stopAuto();
    array = Array.from({ length: ARRAY_SIZE }, () => Math.floor(Math.random() * 90) + 10);
    arrayLenEl.textContent = array.length;
    resetSortState();
    renderBars();
    highlightCode(-1);
  }

  function renderBars() {
    container.innerHTML = '';
    bars = array.map((value, index) => {
      const bar = document.createElement('div');
      bar.className = 'bar';
      bar.style.height = value + '%';
      const label = document.createElement('div');
      label.className = 'bar-label';
      label.textContent = value;
      bar.appendChild(label);
      container.appendChild(bar);
      return bar;
    });
  }

  function resetSortState() {
    steps = [];
    currentStep = 0;
    compareCountEl.textContent = '0';
    swapCountEl.textContent = '0';
    steps = recordBubbleSort([...array]);
    bars.forEach(b => b.classList.remove('compare', 'swap', 'sorted'));
  }

  function recordBubbleSort(arr) {
    const n = arr.length;
    const log = [];
    let compares = 0;
    let swaps = 0;
    const state = [...arr];

    for (let i = 0; i < n - 1; i++) {
      for (let j = 0; j < n - 1 - i; j++) {
        log.push({ type: 'compare', i: j, j: j + 1, line: 4, compares, swaps, state: [...state] });
        compares++;
        if (state[j] > state[j + 1]) {
          log.push({ type: 'swap', i: j, j: j + 1, line: 6, compares, swaps, state: [...state] });
          [state[j], state[j + 1]] = [state[j + 1], state[j]];
          swaps++;
          log.push({ type: 'afterSwap', i: j, j: j + 1, line: 7, compares, swaps, state: [...state] });
        }
      }
      log.push({ type: 'sorted', index: n - 1 - i, line: 8, compares, swaps, state: [...state] });
    }
    log.push({ type: 'sorted', index: 0, line: 10, compares, swaps, state: [...state] });
    return log;
  }

  function applyStep(stepIndex) {
    if (stepIndex < 0 || stepIndex >= steps.length) return;
    const step = steps[stepIndex];
    compareCountEl.textContent = step.compares;
    swapCountEl.textContent = step.swaps;
    highlightCode(step.line);

    bars.forEach((b, idx) => {
      b.style.height = step.state[idx] + '%';
      b.querySelector('.bar-label').textContent = step.state[idx];
      b.classList.remove('compare', 'swap');
    });

    if (step.type === 'compare') {
      bars[step.i].classList.add('compare');
      bars[step.j].classList.add('compare');
    } else if (step.type === 'swap') {
      bars[step.i].classList.add('swap');
      bars[step.j].classList.add('swap');
    } else if (step.type === 'sorted') {
      for (let k = step.index; k < array.length; k++) {
        bars[k].classList.add('sorted');
      }
    }
  }

  function highlightCode(line) {
    codeLines.forEach(el => el.classList.remove('active'));
    if (line >= 0) {
      const el = document.querySelector(`.code-line[data-line="${line}"]`);
      if (el) el.classList.add('active');
    }
  }

  function stepForward() {
    if (currentStep < steps.length) {
      applyStep(currentStep);
      currentStep++;
    } else {
      stopAuto();
    }
  }

  function startAuto() {
    if (currentStep >= steps.length) currentStep = 0;
    isAuto = true;
    btnAuto.textContent = '暂停';
    function tick() {
      if (!isAuto) return;
      stepForward();
      if (currentStep < steps.length) {
        autoTimer = setTimeout(tick, parseInt(speedInput.value, 10));
      } else {
        stopAuto();
      }
    }
    tick();
  }

  function stopAuto() {
    isAuto = false;
    btnAuto.textContent = '自动播放';
    if (autoTimer) clearTimeout(autoTimer);
  }

  btnGenerate.addEventListener('click', generateArray);

  btnSort.addEventListener('click', () => {
    stopAuto();
    currentStep = 0;
    bars.forEach(b => b.classList.remove('sorted'));
    // 快速完成
    const interval = setInterval(() => {
      if (currentStep >= steps.length) {
        clearInterval(interval);
        return;
      }
      applyStep(currentStep);
      currentStep++;
    }, 30);
  });

  btnStep.addEventListener('click', () => {
    stopAuto();
    stepForward();
  });

  btnAuto.addEventListener('click', () => {
    if (isAuto) stopAuto(); else startAuto();
  });

  btnReset.addEventListener('click', () => {
    stopAuto();
    resetSortState();
    renderBars();
    highlightCode(-1);
  });

  speedInput.addEventListener('input', () => {
    speedVal.textContent = speedInput.value + 'ms';
  });

  generateArray();
</script>
</body>
</html>
